WITH parsed AS (SELECT id, service, status_code, payload_json, context['version'] AS version, SIZE(context) AS num_context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['trace'] AS trace, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT *, NTILE(10) OVER w_part AS num_context_bucket, LEAD(num_context, 2, 0) OVER (PARTITION BY service ORDER BY num_context, id) AS next_num_context, ROW_NUMBER() OVER w_running AS row_seq FROM parsed WINDOW w_part AS (ORDER BY num_context, id), w_running AS (PARTITION BY service ORDER BY status_code, id);
